// The expected numbers were generated by unchanged official Java, not this crate.
use audiveris_classifier::{Model, SOURCE_COMMIT, SOURCE_ZIP_SHA256};
use serde::Deserialize;

// Fixed before the first Rust comparison. Do not adjust to accommodate failures.
const ABS_TOL: f64 = 1e-12;
const REL_TOL: f64 = 1e-10;
const MODEL: &[u8] = include_bytes!("../models/audiveris-5.11.0.json");
const GOLDEN: &[u8] = include_bytes!("fixtures/java-5.11.0-golden.json");

#[derive(Deserialize)]
struct Golden {
    audiveris_commit: String,
    model_sha256: String,
    input_labels: Vec<String>,
    output_labels: Vec<String>,
    feature_cases: Vec<Case>,
}
#[derive(Deserialize)]
struct Case {
    id: String,
    raw_features: Vec<f64>,
    normalized: Vec<f64>,
    hidden: Vec<f64>,
    scores: Vec<f64>,
    top5: Vec<Top>,
}
#[derive(Deserialize)]
struct Top {
    index: usize,
    label: String,
    score: f64,
}

#[test]
fn matches_136_official_java_cases_and_55488_values() {
    let model = Model::from_json(MODEL).unwrap();
    let golden: Golden = serde_json::from_slice(GOLDEN).unwrap();
    assert_eq!(golden.audiveris_commit, SOURCE_COMMIT);
    assert_eq!(golden.model_sha256, SOURCE_ZIP_SHA256);
    assert_eq!(model.input_labels(), golden.input_labels);
    assert_eq!(model.output_labels(), golden.output_labels);
    assert_eq!(golden.feature_cases.len(), 136);
    let mut maxima = [0.0_f64; 3];
    let mut count = 0;
    for case in &golden.feature_cases {
        let actual = model.evaluate(&case.raw_features).unwrap();
        let stages = [
            ("normalized", &actual.normalized, &case.normalized, 110),
            ("hidden", &actual.hidden, &case.hidden, 149),
            ("scores", &actual.scores, &case.scores, 149),
        ];
        for (stage, (name, values, references, size)) in stages.iter().enumerate() {
            assert_eq!(values.len(), *size);
            assert_eq!(references.len(), *size);
            for (i, (&value, &reference)) in values.iter().zip(references.iter()).enumerate() {
                assert!(value.is_finite() && reference.is_finite());
                let error = (value - reference).abs();
                let allowed = ABS_TOL + REL_TOL * reference.abs();
                assert!(
                    error <= allowed,
                    "{} {name}[{i}]: actual={value:.17e} expected={reference:.17e} error={error:.17e} tolerance={allowed:.17e}",
                    case.id
                );
                maxima[stage] = maxima[stage].max(error);
                count += 1;
            }
        }
        let mut rank: Vec<usize> = (0..149).collect();
        rank.sort_by(|&a, &b| {
            actual.scores[b]
                .total_cmp(&actual.scores[a])
                .then(a.cmp(&b))
        });
        for (&index, expected) in rank.iter().take(5).zip(&case.top5) {
            assert_eq!(index, expected.index, "{} top5 order", case.id);
            assert_eq!(model.output_labels()[index], expected.label);
            assert!(
                (actual.scores[index] - expected.score).abs()
                    <= ABS_TOL + REL_TOL * expected.score.abs()
            );
        }
    }
    assert_eq!(count, 55_488);
    let report = serde_json::json!({
        "cases": 136, "compared_values": count, "top5_order_match": true,
        "absolute_tolerance": ABS_TOL, "relative_tolerance": REL_TOL,
        "max_absolute_error": {"normalized":maxima[0],"hidden":maxima[1],"scores":maxima[2]},
        "upstream_commit": SOURCE_COMMIT, "source_model_sha256": SOURCE_ZIP_SHA256,
        "golden_sha256": "432e7003d8c2b319575e79c023a6f378cd4f18f9092b5ce47fb8aa1d46dfe983",
        "profile": if cfg!(debug_assertions) {"debug"} else {"release"},
        "production_java_dependency": false
    });
    println!("{}", serde_json::to_string_pretty(&report).unwrap());
    if let Some(path) = std::env::var_os("AUDIVERIS_VALIDATION_REPORT") {
        std::fs::write(path, serde_json::to_vec_pretty(&report).unwrap()).unwrap();
    }
}
